'use strict';

const TASK_SCHEMA_VERSION = 'chelsea_tasks_table_v1';
const COMMAND_CONTRACT_VERSION = 'chelsea_task_command_v1';

function fail(code, message, details) {
  const error = new Error(message || code);
  error.code = code;
  if (details !== undefined) error.details = details;
  throw error;
}

function assert(condition, code, message, details) {
  if (!condition) fail(code, message, details);
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value) &&
    (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null);
}

function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (!isPlainObject(value)) return value;
  const result = {};
  for (const key of Object.keys(value).sort()) result[key] = stableValue(value[key]);
  return result;
}

function canonicalJson(value) {
  return JSON.stringify(stableValue(value));
}

// Portable deterministic 128-bit non-cryptographic hash. It is used for logical
// IDs/idempotency/action tokens, never as a callback signature or secret.
function hash128(input) {
  const text = String(input).normalize('NFKC');
  let h1 = 0xdeadbeef ^ text.length;
  let h2 = 0x41c6ce57 ^ text.length;
  let h3 = 0xc0decafe ^ text.length;
  let h4 = 0x9e3779b9 ^ text.length;
  for (let i = 0; i < text.length; i += 1) {
    const ch = text.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
    h3 = Math.imul(h3 ^ ch, 2246822507);
    h4 = Math.imul(h4 ^ ch, 3266489909);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h3 ^ (h3 >>> 13), 3266489909);
  h3 = Math.imul(h3 ^ (h3 >>> 16), 2246822507) ^ Math.imul(h4 ^ (h4 >>> 13), 3266489909);
  h4 = Math.imul(h4 ^ (h4 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return [h1, h2, h3, h4].map((n) => (n >>> 0).toString(16).padStart(8, '0')).join('');
}

function deterministicId(prefix, parts) {
  assert(/^[a-z][a-z0-9_]*$/.test(prefix), 'invalid_id_prefix', 'Invalid deterministic ID prefix');
  return `${prefix}_${hash128(canonicalJson(parts))}`;
}

function toIso(value, fieldName) {
  const date = value instanceof Date ? new Date(value.getTime()) : new Date(value);
  assert(Number.isFinite(date.getTime()), 'invalid_datetime', `Invalid ${fieldName || 'date-time'}`);
  return date.toISOString();
}

function optionalIso(value, fieldName) {
  return value === null || value === undefined || value === '' ? '' : toIso(value, fieldName);
}

function parseIso(value, fieldName) {
  assert(typeof value === 'string' && /Z$/.test(value), 'invalid_utc_iso', `${fieldName || 'value'} must be UTC ISO ending in Z`);
  const date = new Date(value);
  assert(Number.isFinite(date.getTime()) && date.toISOString() === value, 'invalid_utc_iso', `Invalid ${fieldName || 'UTC instant'}`);
  return date;
}

function asString(value, fieldName, options) {
  const opts = options || {};
  assert(typeof value === 'string', 'invalid_string', `${fieldName} must be a string`);
  const result = opts.trim === false ? value : value.trim();
  const min = opts.min === undefined ? 0 : opts.min;
  const max = opts.max === undefined ? 4096 : opts.max;
  assert(result.length >= min && result.length <= max, 'invalid_string_length', `${fieldName} length is outside allowed bounds`);
  return result;
}

function asInteger(value, fieldName, min, max) {
  assert(Number.isInteger(value), 'invalid_integer', `${fieldName} must be an integer`);
  assert(value >= min && value <= max, 'integer_out_of_range', `${fieldName} is outside allowed bounds`);
  return value;
}

function oneOf(value, allowed, fieldName) {
  assert(allowed.includes(value), 'invalid_enum', `${fieldName} has an unsupported value`, { fieldName, value });
  return value;
}

function exactKeys(object, allowed, fieldName) {
  assert(isPlainObject(object), 'invalid_object', `${fieldName} must be an object`);
  const unexpected = Object.keys(object).filter((key) => !allowed.includes(key));
  assert(unexpected.length === 0, 'unknown_fields', `${fieldName} contains unknown fields`, unexpected);
}

function deepClone(value) {
  return value === undefined ? undefined : JSON.parse(JSON.stringify(value));
}

function appendHistory(historyJson, event) {
  let history = [];
  if (historyJson) {
    try {
      history = JSON.parse(historyJson);
    } catch (_) {
      fail('malformed_history_json', 'historyJson is malformed');
    }
  }
  assert(Array.isArray(history), 'malformed_history_json', 'historyJson must contain an array');
  history.push(event);
  return canonicalJson(history.slice(-20));
}

function mutationToken(recordId, previousVersion, mutationType, sourceId) {
  return deterministicId('mut', [recordId, previousVersion, mutationType, sourceId || 'system']);
}

function actionToken(recordId, type, at, sequence, rowVersion) {
  if (type === 'none') return '';
  return deterministicId('act', [recordId, type, at, sequence, rowVersion]);
}

module.exports = {
  TASK_SCHEMA_VERSION,
  COMMAND_CONTRACT_VERSION,
  fail,
  assert,
  isPlainObject,
  stableValue,
  canonicalJson,
  hash128,
  deterministicId,
  toIso,
  optionalIso,
  parseIso,
  asString,
  asInteger,
  oneOf,
  exactKeys,
  deepClone,
  appendHistory,
  mutationToken,
  actionToken,
};

};
__modules['./identity'] = function(module, exports, __require) {
'use strict';

const { assert, asString, oneOf, toIso } = __require('./utils');

const INPUT_TYPES = ['text', 'caption', 'voice_transcript', 'callback', 'reply'];

function deriveCanonicalIdentity(value) {
  const input = value && typeof value === 'object' ? value : { storageUsername: value, userId: value, telegramUserId: value };
  const principalKey = String(input.principalKey ?? '').trim();
  const storageUsername = String(input.storageUsername ?? input.userId ?? input.telegramUserId ?? '').normalize('NFKC').trim().replace(/^@+/, '').toLowerCase();
  const currentUsername = String(input.currentUsername ?? input.telegramUsername ?? storageUsername).normalize('NFKC').trim().replace(/^@+/, '').toLowerCase();
  if (principalKey) assert(/^tguser_[a-f0-9]{64}$/.test(principalKey), 'identity_permanent', 'principalKey must be derived from the canonical Telegram username');
  assert(/^[a-z0-9_]{1,64}$/.test(storageUsername), 'identity_permanent', 'storageUsername is invalid');
  assert(!currentUsername || /^[a-z0-9_]{1,64}$/.test(currentUsername), 'identity_permanent', 'currentUsername is invalid');
  const expected = { userId: storageUsername, tenantId: `tenant_${storageUsername}` };
  if (input.userId !== undefined) assert(String(input.userId || '') === expected.userId, 'identity_permanent', 'username userId mismatch');
  if (input.tenantId !== undefined) assert(String(input.tenantId || '') === expected.tenantId, 'identity_permanent', 'username tenantId mismatch');
  return { principalKey, storageUsername, currentUsername, telegramUserId: storageUsername, userId: expected.userId, tenantId: expected.tenantId, identitySchemaVersion: 'chelsea_username_identity_v1' };
}

function deriveTenantTable(tenantId) {
  const tenantSafe = asString(tenantId, 'tenantId', { min: 1, max: 128 });
  assert(/^[A-Za-z0-9_-]+$/.test(tenantSafe), 'identity_permanent', 'Derived tenantSafe is not table-safe');
  return { tenantSafe, tableName: `Chelsea Tasks ${tenantSafe}` };
}

// rawTrusted must be built from the Telegram trigger/server route. Semantic model
// output is intentionally a separate argument and cannot influence this function.
function normalizeTrustedInput(rawTrusted, options) {
  const input = rawTrusted || {};
  const identity = deriveCanonicalIdentity(input);
  const table = deriveTenantTable(identity.tenantId);
  const chatId = asString(String(input.chatId === undefined ? '' : input.chatId), 'chatId', { min: 1, max: 64 });
  assert(/^-?\d+$/.test(chatId), 'identity_permanent', 'chatId must be numeric');
  const messageId = asString(String(input.messageId === undefined ? '' : input.messageId), 'messageId', { min: 1, max: 64 });
  assert(/^\d+$/.test(messageId), 'identity_permanent', 'messageId must be numeric');
  const sourceUpdateId = input.sourceUpdateId === undefined || input.sourceUpdateId === null
    ? '' : asString(String(input.sourceUpdateId), 'sourceUpdateId', { max: 64 });
  const sourceMessageDateIso = toIso(input.sourceMessageDateIso, 'sourceMessageDateIso');
  const sourceInputType = oneOf(input.sourceInputType || 'text', INPUT_TYPES, 'sourceInputType');
  const timezone = asString((options && options.timezone) || input.trustedTimezone || 'Asia/Novosibirsk', 'timezone', { min: 1, max: 64 });
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: timezone }).format(new Date());
  } catch (_) {
    assert(false, 'identity_permanent', 'Trusted timezone is invalid');
  }
  return Object.freeze({
    ...identity,
    ...table,
    chatId,
    messageId,
    sourceUpdateId,
    sourceMessageDateIso,
    sourceInputType,
    timezone,
    registryLookup: Object.freeze({ tableId: 'EXhULstmn5lQSz1O', column: 'User', exactValue: identity.tenantId }),
  });
}

function verifyRegistryRows(rows, trusted) {
  assert(Array.isArray(rows), 'identity_permanent', 'Folder users lookup must return an array');
  const exact = rows.filter((row) => row && row.User === trusted.tenantId);
  assert(exact.length === 1, 'identity_permanent', 'Folder users must contain exactly one exact tenant row', { count: exact.length });
  return { allowed: true, row: exact[0], tableName: trusted.tableName, createAllowedForCommandOnly: true };
}

module.exports = {
  INPUT_TYPES,
  deriveCanonicalIdentity,
  deriveTenantTable,
  normalizeTrustedInput,
  verifyRegistryRows,
};

};
__modules['./intent'] = function(module, exports, __require) {
'use strict';

const { asString } = __require('./utils');

const EXPLICIT_TASK = [
  /(?:напомни|напомнить|поставь\s+(?:задачу|напоминание)|создай\s+(?:задачу|напоминание)|запланируй|добавь\s+(?:задачу|напоминание))/iu,
  /(?:задач[ауи]|напоминани[ея]|дедлайн|срок).*(?:создай|добавь|перенеси|отмени|удали|закрой|выполнен)/iu,
  /\b(?:remind me|create (?:a )?task|add (?:a )?reminder|schedule (?:a )?task)\b/iu,
];
const LIST_TASKS = /^(?:покажи|покажи мне|какие|список)\s+(?:мои\s+)?(?:задачи|напоминания)(?:\s|$)/iu;
const MUTATION = /^(?:выполнено|сделал(?:а)?|готово|отложи|перенеси|пропусти|отмени)(?:\s|$)/iu;
const IMPERATIVE_WITH_TIME = /^(?:купить|позвонить|сделать|отправить|проверить|забрать|записаться|оплатить|выключить|подготовить)(?:\s|$)[\s\S]{0,160}(?:сегодня|завтра|послезавтра|через\s+\d+|в\s+\d{1,2}(?::\d{2})?|в\s+(?:понедельник|вторник|среду|четверг|пятницу|субботу|воскресенье))/iu;
const CONVERSATIONAL = /^(?:как|почему|что\s+ты\s+думаешь|расскажи|объясни|помоги\s+понять|можешь\s+ли\s+обсудить)(?:\s|,|$)/iu;
const AMBIGUOUS = /(?:надо|нужно|хочу|не забыть|когда-нибудь|в ближайшее время)/iu;
const RECURRING_CADENCE_AT_START = /^(?:(?:добавь|запланируй|создай)\s+)?(?:ежедневно|еженедельно|ежемесячно|кажд(?:ый|ую|ое)\s+(?:день|утро|вечер|неделю|месяц|понедельник|вторник|среду|четверг|пятницу|субботу|воскресенье))(?:\s|$)/iu;
const RECURRING_CADENCE_AT_END = /(?:^|\s)по\s+(?:утрам|вечерам|будням|выходным|понедельникам|вторникам|средам|четвергам|пятницам|субботам|воскресеньям)[.!…]*$/iu;
const RECURRING_ACTIVITY = /(?:^|[^\p{L}\p{N}_])(?:зарядк[ауи]?|тренировк[ауи]?|пробежк[ауи]?|медитаци[яюи]|чтени[ея]|прогулк[ауи]?|уборк[ауи]?)(?=$|[^\p{L}\p{N}_])|(?:^|\s)[\p{L}-]{3,}(?:ть|ти|чь)(?=$|\s|[.,!…])/iu;

function taskIntentGate(input) {
  const source = input || {};
  const text = asString(String(source.text || ''), 'text', { max: 12000 });
  if (source.isEdited) return decision('not_a_task_command', false, 'edited_updates_are_not_task_mutations');
  if (source.isForwarded) return decision('not_a_task_command', false, 'forwarded_content_is_not_user_task_intent');
  if (source.inputType === 'callback' || source.callbackScope === 'chelsea_task_v1') {
    return decision('task_answer', true, 'server_correlated_task_callback');
  }
  if (source.replyToTaskQuestion === true) return decision('task_answer', true, 'server_correlated_task_reply');
  if (!text) return decision('not_a_task_command', false, 'empty_text');
  if (LIST_TASKS.test(text)) return decision('task_command', true, 'explicit_task_list');
  if (EXPLICIT_TASK.some((pattern) => pattern.test(text))) return decision('task_command', true, 'explicit_task_vocabulary');
  if (IMPERATIVE_WITH_TIME.test(text)) return decision('task_command', true, 'imperative_with_explicit_time');
  if (looksLikeRecurringActivity(text)) return decision('task_command', true, 'bounded_recurring_activity');
  if (looksLikeBareAction(text)) return decision('task_command', true, 'bounded_bare_action');
