    return decision('ambiguous', false, 'task_answer_requires_exact_correlation', 'target');
  }
  if (CONVERSATIONAL.test(text)) return decision('not_a_task_command', false, 'conversational_request');
  if (AMBIGUOUS.test(text)) return decision('ambiguous', false, 'task_or_dialog_requires_confirmation', 'confirmation');
  return decision('not_a_task_command', false, 'no_conservative_task_signal');
}

function looksLikeRecurringActivity(text) {
  const value = String(text || '').normalize('NFKC').trim();
  if (!value || value.length > 240 || /[?？]/u.test(value)) return false;
  const tokens = value.replace(/[.!…]+$/u, '').split(/\s+/u).filter(Boolean);
  if (tokens.length < 2 || tokens.length > 14) return false;
  if (!RECURRING_CADENCE_AT_START.test(value) && !RECURRING_CADENCE_AT_END.test(value)) return false;
  if (!RECURRING_ACTIVITY.test(value)) return false;
  if (CONVERSATIONAL.test(value) || /^(?:я|мы|он|она|они|ты|вы|мне|нам|ему|ей|им)\s/iu.test(value)) return false;
  if (/(?:^|[^\p{L}\p{N}_])(?:сложн[а-яё]*|легк[а-яё]*|важн[а-яё]*|полезн[а-яё]*|вредн[а-яё]*|хорош[а-яё]*|плох[а-яё]*|нравится|люблю|ненавижу|значит|означает)(?=$|[^\p{L}\p{N}_])/iu.test(value)) return false;
  return true;
}

function looksLikeBareAction(text) {
  const value = String(text || '').normalize('NFKC').trim();
  if (!value || value.length > 240 || /[?？]/u.test(value)) return false;
  const tokens = value.replace(/[.!…]+$/u, '').split(/\s+/u).filter(Boolean);
  if (tokens.length < 2 || tokens.length > 12) return false;
  const first = tokens[0].replace(/^[^\p{L}]+|[^\p{L}-]+$/gu, '');
  if (!/^[\p{L}-]{3,}(?:ть|ти|чь)$/iu.test(first)) return false;
  // Infinitive-led explanations and value judgments are ordinary dialogue,
  // not safe task commands. This remains structural and topic-neutral.
  if (/(?:^|[^\p{L}\p{N}_])(?:сложно|легко|важно|полезно|вредно|хорошо|плохо|значит|означает|нужно|надо|можно|нельзя|приятно|интересно)(?=$|[^\p{L}\p{N}_])/iu.test(value)) return false;
  if (/[—–-]\s*(?:это|значит|означает)/iu.test(value)) return false;
  if (/^(?:я|мы|он|она|они|ты|вы)\s/iu.test(value)) return false;
  return true;
}

function decision(route, taskHandled, reason, expectedAnswerType) {
  const ambiguous = route === 'ambiguous';
  return {
    route,
    taskHandled,
    taskClarification: ambiguous,
    expectedAnswerType: expectedAnswerType || null,
    memoryWriteAllowed: route === 'not_a_task_command',
    reason,
  };
}

module.exports = { taskIntentGate, looksLikeBareAction, looksLikeRecurringActivity };

};
__modules['./semantic'] = function(module, exports, __require) {
'use strict';

const {
  COMMAND_CONTRACT_VERSION, assert, isPlainObject, exactKeys, asString,
  asInteger, oneOf, canonicalJson,
} = __require('./utils');

const OPERATIONS = [
  'create_task', 'create_reminder', 'add_reminder', 'update_task', 'reschedule_task',
  'complete_task', 'snooze_task', 'skip_occurrence', 'cancel_task', 'list_tasks',
  'add_subtask', 'pause_series', 'resume_series', 'update_series', 'cancel_series',
  'answer_task_question', 'not_a_task_command',
];
const TOP_KEYS = [
  'contractVersion', 'operation', 'targetRef', 'title', 'description', 'taskKind',
  'priority', 'tags', 'schedule', 'recurrence', 'reminderPolicy', 'completionRequired',
  'seriesMutationScope', 'listKind', 'answerAction', 'clarificationNeeded', 'clarificationReason',
  'fieldPresence',
];
const PATCH_FIELDS = Object.freeze(['title', 'description', 'taskKind', 'priority', 'tags', 'schedule', 'recurrence', 'reminderPolicy', 'completionRequired', 'seriesMutationScope']);
const FORBIDDEN_IDENTITY_KEYS = [
  'tenantId', 'tenantSafe', 'taskTableId', 'tableId', 'tableName', 'ownerUserId',
  'recordId', 'taskId', 'seriesId', 'status', 'rowVersion', 'actionToken', 'idempotencyKey',
];

function parseSemanticJson(value) {
  let parsed = value;
  if (typeof value === 'string') {
    const text = value.trim();
    assert(text.startsWith('{') && text.endsWith('}'), 'malformed_model_contract', 'Model result must be one JSON object without prose/code fences');
    try { parsed = JSON.parse(text); } catch (_) {
      assert(false, 'malformed_model_contract', 'Model result is not valid JSON');
    }
  }
  assert(isPlainObject(parsed), 'malformed_model_contract', 'Model result must be an object');
  // Identity-like model fields are ignored by design; all other unknown fields fail closed.
  const clean = {};
  for (const [key, item] of Object.entries(parsed)) {
    if (!FORBIDDEN_IDENTITY_KEYS.includes(key)) clean[key] = item;
