  planned.askedMessageId = String(receipt.messageId); planned.telegramActionMessageId = String(receipt.messageId); planned.telegramActionChatId = String(receipt.chatId);
  planned.lastDeliveryOutcome = 'delivered';
  planned.historyJson = appendHistory(planned.historyJson, {
    eventId: deterministicId('evt', [draftRow.recordId, 'draft_question_receipt', receipt.messageId]), eventType: 'draft_question_delivered', at,
    actor: 'system', sourceMessageId: draftRow.sourceMessageId, mutationToken: planned.lastMutationToken, diff: { askedMessageId: planned.askedMessageId },
  });
