function planResolveMutationDraft(draftRow, targetRow, answer, trusted, nowIso) {
  draftRow = validatePersistedRow(draftRow, { trusted }); targetRow = validatePersistedRow(targetRow, { trusted });
  assert(draftRow.rowRole === 'command_draft' && draftRow.draftKind === 'mutation', 'invalid_draft', 'Expected a mutation command draft');
  assert(answer && String(answer.correlationToken || '') === draftRow.correlationToken, 'correlation_mismatch', 'Mutation draft token mismatch');
  assert(String(answer.selectedRecordId || '') === targetRow.recordId, 'correlation_mismatch', 'Selected target does not match exact target row');
  const answerMessageId = String(answer.answerMessageId || '');
  assert(/^\d+$/.test(answerMessageId), 'correlation_mismatch', 'Mutation draft answerMessageId must be numeric');
  const answerIdempotencyKey = deterministicId('idem', ['task_answer', trusted.tenantId, trusted.chatId, answerMessageId, draftRow.recordId, targetRow.recordId]);
  if (draftRow.status === 'completed' && draftRow.answerIdempotencyKey === answerIdempotencyKey) {
    return { idempotent: true, mutationRequired: false, rows: [deepClone(targetRow), deepClone(draftRow)], taskHandled: true, memoryWriteAllowed: false };
  }
  assert(draftRow.status === 'draft' && draftRow.expectedAnswerType === 'target', 'invalid_draft', 'Mutation draft is not awaiting target selection');
  assert(/^\d+$/.test(draftRow.askedMessageId || ''), 'correlation_mismatch', 'Mutation draft has no confirmed askedMessageId receipt');
  assert(['reply', 'callback'].includes(answer.mode), 'correlation_mismatch', 'Mutation draft answer mode is invalid');
  if (answer.mode === 'reply') assert(String(answer.replyToMessageId || '') === draftRow.askedMessageId, 'correlation_mismatch', 'Mutation draft reply does not target askedMessageId');
  else assert(String(answer.callbackMessageId || '') === draftRow.askedMessageId && answer.callbackScope === draftRow.callbackScope, 'correlation_mismatch', 'Mutation draft callback does not target exact question');
  if (draftRow.answerExpiresAt && new Date(nowIso) > new Date(draftRow.answerExpiresAt)) {
    assert(answer.allowLateExact === true, 'stale_answer', 'Mutation draft answer expired');
  }
  assert(answer.expectedDraftRowVersion === draftRow.rowVersion && answer.expectedTargetRowVersion === targetRow.rowVersion, 'concurrency_conflict', 'Mutation draft resolution uses stale rowVersion');
  const candidateIds = JSON.parse(draftRow.candidateTaskIdsJson || '[]');
  assert(Array.isArray(candidateIds) && candidateIds.includes(targetRow.recordId), 'correlation_mismatch', 'Selected target is outside persisted candidate set');
  assert(targetRow.tenantId === draftRow.tenantId && targetRow.ownerUserId === draftRow.ownerUserId && targetRow.chatId === draftRow.chatId, 'identity_permanent', 'Mutation draft target identity mismatch');
  const command = parseSemanticJson(draftRow.pendingCommandJson);
  const at = new Date(nowIso).toISOString();
  const history = JSON.parse(targetRow.historyJson || '[]');
  const alreadyApplied = history.some((event) => event && event.diff && event.diff.mutationDraftAnswerKey === answerIdempotencyKey);
  let targetPlan = null;
