  if (draftRow.answerExpiresAt && new Date(at) > new Date(draftRow.answerExpiresAt)) {
    assert(answer.allowLateExact === true, 'stale_answer', 'Create draft answer expired');
  }
  assert(answer.expectedDraftRowVersion === draftRow.rowVersion, 'concurrency_conflict', 'Create draft resolution uses stale rowVersion');
  const combinedText = `${draftRow.originalText || ''}\n${String(answer.answerText || '')}`.trim();
  validateSemanticAgainstTrusted(resolvedCommand, { ...trusted, sourceMessageDateIso: at }, combinedText);
