    'sourceUpdateId', 'sourceMessageId', 'sourceMessageDateIso', 'sourceInputType', 'idempotencyKey']) planned[key] = draftRow[key];
  planned.recordType = 'task'; planned.rowRole = 'standalone'; planned.seriesId = ''; planned.occurrenceKey = '';
  planned.rowVersion = draftRow.rowVersion + 1;
  planned.lastMutationToken = mutationToken(draftRow.recordId, draftRow.rowVersion, 'resolve_create_draft', answerMessageId);
  planned.draftKind = ''; planned.pendingCommandJson = ''; planned.candidateTaskIdsJson = '[]'; planned.expectedAnswerType = '';
  planned.correlationToken = ''; planned.answerMessageId = answerMessageId; planned.answerIdempotencyKey = answerIdempotencyKey; planned.answerExpiresAt = '';
  planned.askedMessageId = draftRow.askedMessageId;
  planned.telegramActionMessageId = ''; planned.telegramActionChatId = '';
  planned.leaseOwner = ''; planned.leaseUntil = ''; planned.dispatchToken = '';
  planned.actionToken = actionToken(planned.recordId, planned.nextActionType, planned.nextActionAt, planned.actionSequence, planned.rowVersion);
  planned.historyJson = appendHistory(draftRow.historyJson, {
    eventId: deterministicId('evt', [draftRow.recordId, 'create_draft_resolved', answerIdempotencyKey]),
    eventType: 'create_draft_resolved', at, actor: 'user', sourceMessageId: answerMessageId,
    mutationToken: planned.lastMutationToken,
    diff: { operation: resolvedCommand.operation, answerIdempotencyKey },
  });
  validatePlannedRow(planned, { trusted });
  return {
    idempotent: false, mutationRequired: true, row: planned, answerIdempotencyKey,
    readBackExpectation: mutationReadBackExpectation(draftRow, planned),
    writeOrder: ['transform_create_draft_in_place'],
    recovery: 'same_record_identity_cas', taskHandled: true, memoryWriteAllowed: false,
