  const checked = validateTaskAnswer(row, answer, trusted, nowIso);
  if (checked.idempotent) return { ...checked, mutationRequired: false, taskHandled: true, memoryWriteAllowed: false };
  assertUserMutationLeaseFree(row, nowIso);
  if (answer.action === 'not_done') return { mutationRequired: false, requiresChoice: true, choices: ['snooze', 'reschedule', 'keep_pending'], answerIdempotencyKey: checked.answerIdempotencyKey, taskHandled: true, memoryWriteAllowed: false };
  const planned = deepClone(row);
  const previousVersion = row.rowVersion;
  const nextVersion = previousVersion + 1;
  const at = new Date(nowIso).toISOString();
  planned.rowVersion = nextVersion;
  planned.lastMutationToken = mutationToken(row.recordId, previousVersion, `answer_${answer.action}`, answer.answerMessageId);
  planned.answerMessageId = String(answer.answerMessageId);
  planned.answerIdempotencyKey = checked.answerIdempotencyKey;
  planned.lastAnswerText = String(answer.answerText || '').slice(0, 1000);
  planned.answerExpiresAt = '';
  // A confirmed question is single-use. A later completion question receives
  // a fresh server token only at its own dispatch-mark/read-back boundary.
  planned.correlationToken = ''; planned.askedMessageId = ''; planned.expectedAnswerType = '';
  planned.leaseOwner = ''; planned.leaseUntil = ''; planned.dispatchToken = '';

  if (answer.action === 'done') terminalize(planned, 'completed', 'user_confirmed_done', at, planned.rowRole === 'occurrence');
  if (answer.action === 'skip_occurrence') {
    assert(planned.rowRole === 'occurrence', 'invalid_transition', 'Only an occurrence can be skipped');
    terminalize(planned, 'skipped', 'user_skipped_occurrence', at, true);
  }
  if (answer.action === 'cancel') terminalize(planned, 'cancelled', 'user_cancelled', at, planned.rowRole === 'occurrence');
  if (answer.action === 'snooze') {
    const until = answer.snoozedUntil
      ? new Date(answer.snoozedUntil)
      : new Date(new Date(at).getTime() + boundedMinutes(answer.snoozeMinutes || 60) * 60000);
    assert(Number.isFinite(until.getTime()) && until > new Date(at), 'invalid_snooze', 'Snooze must end in the future');
    const resumeType = row.status === 'awaiting_confirmation' ? 'ask_completion' : (row.nextActionType === 'none' ? 'send_reminder' : row.nextActionType);
    planned.status = 'snoozed'; planned.statusReason = 'user_snoozed'; planned.stateChangedAt = at; planned.snoozedUntil = until.toISOString();
    setNextAction(planned, resumeType, planned.snoozedUntil, row.actionSequence + 1, nextVersion);
  }
  if (answer.action === 'reschedule') {
    assert(answer.schedule, 'invalid_reschedule', 'reschedule requires a validated schedule');
    const preservedRecurrence = planned.recurrenceRuleJson;
    const resolved = resolveSchedule(answer.schedule, row.sourceMessageDateIso, row.timezone);
    assert(resolved.scheduleKind !== 'none', 'invalid_reschedule', 'Reschedule cannot remove the schedule');
    Object.assign(planned, resolved);
    planned.status = 'pending'; planned.statusReason = 'user_rescheduled'; planned.stateChangedAt = at; planned.snoozedUntil = ''; planned.reminderCursor = 0;
    setNextAction(planned, 'none', '', row.actionSequence + 1, nextVersion);
    planInitialTaskAction(planned, at);
    assert(planned.recurrenceRuleJson === preservedRecurrence, 'contract_violation', 'Rescheduling current occurrence changed recurrence');
  }
  planned.historyJson = appendHistory(planned.historyJson, {
    eventId: deterministicId('evt', [planned.recordId, answer.action, at, answer.answerMessageId]),
    eventType: `answer_${answer.action}`, at, actor: 'user', sourceMessageId: String(answer.answerMessageId), mutationToken: planned.lastMutationToken, diff: { status: planned.status },
  });
  validatePlannedRow(planned, { trusted });
  return {
    mutationRequired: true,
    row: planned,
    answerIdempotencyKey: checked.answerIdempotencyKey,
    readBackExpectation: mutationReadBackExpectation(row, planned),
    taskHandled: true,
    memoryWriteAllowed: false,
  };
}

const DIRECT_MUTATION_OPERATIONS = Object.freeze([
  'complete_task', 'snooze_task', 'skip_occurrence', 'cancel_task',
  'reschedule_task', 'update_task', 'add_reminder', 'pause_series', 'resume_series',
]);

function planDirectTaskMutation(row, command, trusted, nowIso, options) {
  row = validatePersistedRow(row, { trusted });
  assert(command && DIRECT_MUTATION_OPERATIONS.includes(command.operation), 'unsupported_operation', 'Operation is not a bounded direct mutation');
  validateSemanticAgainstTrusted(command, trusted, (options && options.originalText) || row.originalText || '');
  const at = new Date(nowIso).toISOString();
  const sourceId = String((options && options.sourceMessageId) || trusted.messageId || 'command');
  const sourceUpdateId = String((options && options.sourceUpdateId) || trusted.sourceUpdateId || '');
  assert(sourceId && sourceUpdateId, 'invalid_command_source', 'Direct mutation requires trusted Telegram update/message identity');
  const sourceKey = deterministicId('cmd_src', [trusted.tenantId, trusted.chatId, sourceUpdateId, sourceId, row.recordId]);
  const payloadKey = directCommandPayloadKey(command, options);
  const previousEvents = JSON.parse(row.historyJson || '[]');
  const previousSourceUse = previousEvents.find((event) => event && event.diff && event.diff.directCommandSourceKey === sourceKey);
  if (previousSourceUse) {
    assert(previousSourceUse.diff.directCommandOperation === command.operation && previousSourceUse.diff.directCommandPayloadKey === payloadKey,
      'command_source_reuse_mismatch', 'Telegram source message was already used for a different mutation or payload');
    return {
      idempotent: true, mutationRequired: false, row: deepClone(row),
      idempotencyEvidence: { sourceKey, payloadKey, operation: command.operation },
      readBackExpectation: exactCurrentRowExpectation(row),
    };
  }
  assertUserMutationLeaseFree(row, at);

  const taskOperations = ['complete_task', 'snooze_task', 'skip_occurrence', 'cancel_task', 'reschedule_task', 'update_task', 'add_reminder'];
  const seriesOperations = ['pause_series', 'resume_series'];
  if (taskOperations.includes(command.operation)) {
    assert(row.recordType === 'task' && row.rowRole !== 'command_draft', 'invalid_transition', 'Direct task mutation requires a non-draft task row');
    const sameTerminal = (command.operation === 'complete_task' && row.status === 'completed') ||
      (command.operation === 'cancel_task' && row.status === 'cancelled') ||
      (command.operation === 'skip_occurrence' && row.status === 'skipped');
    if (sameTerminal) {
      return { idempotent: true, mutationRequired: false, row: deepClone(row), terminalAlreadyApplied: true, readBackExpectation: exactCurrentRowExpectation(row) };
    }
    assert(!['completed', 'skipped', 'missed', 'cancelled', 'failed_review'].includes(row.status),
      'historical_task_immutable', 'Terminal task history cannot be reopened or mutated in place');
    assert(['pending', 'awaiting_confirmation', 'snoozed'].includes(row.status), 'invalid_transition', 'Task status does not permit a direct mutation');
  } else if (seriesOperations.includes(command.operation)) {
    assert(row.recordType === 'series', 'invalid_series_transition', 'Series operation requires an exact series row');
  }
  const planned = deepClone(row);
  planned.rowVersion += 1;
  planned.lastMutationToken = mutationToken(row.recordId, row.rowVersion, command.operation, sourceId);
  planned.leaseOwner = ''; planned.leaseUntil = ''; planned.dispatchToken = '';

  if (command.operation === 'complete_task') terminalize(planned, 'completed', 'user_command_completed', at, row.rowRole === 'occurrence');
  else if (command.operation === 'cancel_task') terminalize(planned, 'cancelled', 'user_command_cancelled', at, row.rowRole === 'occurrence');
  else if (command.operation === 'skip_occurrence') {
    assert(row.rowRole === 'occurrence', 'invalid_transition', 'Only occurrence can be skipped');
    terminalize(planned, 'skipped', 'user_command_skipped', at, true);
  } else if (command.operation === 'snooze_task') {
    const until = command.schedule && command.schedule.kind === 'exact'
      ? resolveSchedule(command.schedule, trusted.sourceMessageDateIso, trusted.timezone).dueAt
      : new Date(new Date(at).getTime() + Number((options && options.snoozeMinutes) || 60) * 60000).toISOString();
    assert(Number.isFinite(new Date(until).getTime()) && new Date(until) > new Date(at), 'invalid_snooze', 'Snooze must end in the future');
    planned.status = 'snoozed'; planned.statusReason = 'user_command_snoozed'; planned.stateChangedAt = at; planned.snoozedUntil = until;
    setNextAction(planned, row.nextActionType === 'none' ? 'send_reminder' : row.nextActionType, until, row.actionSequence + 1, planned.rowVersion);
  } else if (command.operation === 'reschedule_task') {
    assert(command.schedule && command.schedule.kind !== 'none', 'invalid_reschedule', 'Reschedule requires an exact/date/window schedule');
    const recurrence = planned.recurrenceRuleJson;
    Object.assign(planned, resolveSchedule(command.schedule, trusted.sourceMessageDateIso, trusted.timezone));
    planned.status = 'pending'; planned.statusReason = 'user_command_rescheduled'; planned.stateChangedAt = at; planned.snoozedUntil = ''; planned.reminderCursor = 0;
    setNextAction(planned, 'none', '', row.actionSequence + 1, planned.rowVersion); planInitialTaskAction(planned, at);
    assert(planned.recurrenceRuleJson === recurrence, 'contract_violation', 'Current reschedule changed recurrence');
  } else if (command.operation === 'update_task') {
    if (fieldProvided(command, 'title')) {
      assert(command.title, 'invalid_update', 'Task title cannot be cleared');
      planned.title = command.title;
    }
    if (fieldProvided(command, 'description')) planned.description = command.description;
    if (fieldProvided(command, 'priority') && command.priority !== null) planned.priority = command.priority;
    if (fieldProvided(command, 'tags') && command.tags !== null) planned.tagsJson = canonicalJson(command.tags);
    planned.statusReason = 'user_command_updated'; planned.stateChangedAt = at;
    planned.actionToken = actionToken(planned.recordId, planned.nextActionType, planned.nextActionAt, planned.actionSequence, planned.rowVersion);
  } else if (command.operation === 'add_reminder') {
    if (command.schedule && command.schedule.kind !== 'none') {
      Object.assign(planned, resolveSchedule(command.schedule, trusted.sourceMessageDateIso, trusted.timezone));
      planned.snoozedUntil = '';
    }
    assert(['exact', 'date'].includes(planned.scheduleKind), 'invalid_reminder_schedule', 'Reminder requires an existing or supplied exact/date schedule');
    const policy = command.reminderPolicy || DEFAULT_REMINDER_POLICY;
    planned.reminderPolicyJson = canonicalJson(policy); planned.reminderEnabled = true; planned.reminderCursor = 0;
    setNextAction(planned, 'none', '', row.actionSequence + 1, planned.rowVersion); planInitialTaskAction(planned, at);
  } else if (command.operation === 'pause_series') {
    assert(row.recordType === 'series' && row.status === 'active', 'invalid_series_transition', 'Only active series can be paused');
    planned.status = 'paused'; planned.statusReason = 'user_paused_series'; planned.stateChangedAt = at;
    setNextAction(planned, 'none', '', row.actionSequence + 1, planned.rowVersion);
  } else if (command.operation === 'resume_series') {
    assert(row.recordType === 'series' && row.status === 'paused', 'invalid_series_transition', 'Only paused series can be resumed');
    assert(!row.currentOccurrenceId, 'series_resume_requires_current_occurrence_resolution', 'Paused series with a current occurrence requires the bounded resume saga');
    planned.status = 'active'; planned.statusReason = 'user_resumed_series'; planned.stateChangedAt = at;
    const rule = JSON.parse(row.recurrenceRuleJson);
    const slot = __require('./time').nextRecurrenceSlot(rule, at, row.recurrenceStartLocalDate, row.recurrenceEndLocalDate || null,
      row.seriesCompletedCount + row.seriesSkippedCount + row.seriesMissedCount);
    if (slot) {
      planned.nextOccurrenceAt = slot.utc;
      setNextAction(planned, 'create_next_occurrence', at, row.actionSequence + 1, planned.rowVersion);
    } else {
      planned.status = 'completed'; planned.statusReason = 'recurrence_finished'; planned.terminalAt = at; planned.nextOccurrenceAt = '';
      setNextAction(planned, 'none', '', row.actionSequence + 1, planned.rowVersion);
    }
  }
  planned.historyJson = appendHistory(planned.historyJson, {
    eventId: deterministicId('evt', [planned.recordId, command.operation, sourceId, planned.rowVersion]),
    eventType: command.operation, at, actor: 'user', sourceMessageId: sourceId,
    mutationToken: planned.lastMutationToken,
    diff: { status: planned.status, directCommandSourceKey: sourceKey, directCommandOperation: command.operation, directCommandPayloadKey: payloadKey },
  });
  validatePlannedRow(planned, { trusted });
  return {
    idempotent: false, row: planned, mutationRequired: true,
    idempotencyEvidence: { sourceKey, payloadKey, operation: command.operation },
    readBackExpectation: mutationReadBackExpectation(row, planned),
  };
}

function directCommandPayloadKey(command, options) {
  const boundedOptions = { snoozeMinutes: options && options.snoozeMinutes === undefined ? null : Number(options && options.snoozeMinutes) };
  if (command.canonicalJson) return deterministicId('cmd_payload', [command.canonicalJson, boundedOptions]);
  const payload = deepClone(command); delete payload.canonicalJson;
  return deterministicId('cmd_payload', [canonicalJson(payload), boundedOptions]);
}

function exactCurrentRowExpectation(row) {
  return {
    exactKey: { recordId: row.recordId, tenantId: row.tenantId, ownerUserId: row.ownerUserId },
    expectedRowVersion: row.rowVersion, expectedMutationToken: row.lastMutationToken,
    immutable: {
      recordId: row.recordId, tenantId: row.tenantId, ownerUserId: row.ownerUserId,
      telegramUserId: row.telegramUserId, chatId: row.chatId,
      sourceMessageId: row.sourceMessageId, sourceMessageDateIso: row.sourceMessageDateIso,
    },
    expectedRow: deepClone(row), requireExactlyOne: true,
  };
}

function assertUserMutationLeaseFree(row, nowIso) {
  const now = new Date(nowIso);
  assert(Number.isFinite(now.getTime()), 'invalid_datetime', 'User mutation time is invalid');
  assert(!row.dispatchToken, 'concurrency_conflict', 'A persisted external dispatch must be finalized or reconciled before user mutation');
  assert(!row.leaseOwner || !row.leaseUntil || new Date(row.leaseUntil) <= now,
    'concurrency_conflict', 'A live scheduler lease owns this row snapshot');
  return true;
}

function planMutationDraft(command, candidates, trusted, originalText, options) {
  assert(command && !['create_task', 'create_reminder', 'add_subtask', 'list_tasks', 'not_a_task_command', 'answer_task_question'].includes(command.operation), 'unsupported_operation', 'Mutation draft requires a mutation operation');
  assert(command.clarificationNeeded === true, 'invalid_draft', 'Mutation draft command must require clarification');
  assert(Array.isArray(candidates) && candidates.length > 0 && candidates.length <= 20, 'invalid_draft', 'Mutation draft requires bounded candidates');
  const rows = candidates.map((row) => validatePersistedRow(row, { trusted }));
  const candidateIds = Array.from(new Set(rows.map((row) => row.recordId))).sort();
  assert(candidateIds.length === rows.length, 'duplicate_logical_row', 'Mutation draft candidates must be unique');
  const token = requireOpaqueDraftToken(options && options.correlationToken);
  const idempotencyKey = deterministicId('idem', ['task_draft', trusted.tenantId, trusted.chatId, trusted.messageId, command.operation]);
  const recordId = deterministicId('draft', [idempotencyKey]);
  const draft = baseRow(trusted, { recordId, recordType: 'task', rowRole: 'command_draft', idempotencyKey });
  draft.status = 'draft'; draft.statusReason = 'mutation_target_clarification_required'; draft.draftKind = 'mutation';
  draft.title = command.title || 'Уточнение изменения задачи'; draft.originalText = String(originalText || '').slice(0, 8000);
  draft.pendingCommandJson = command.canonicalJson; draft.candidateTaskIdsJson = canonicalJson(candidateIds);
  draft.expectedAnswerType = 'target'; draft.correlationToken = token;
  draft.answerExpiresAt = new Date(new Date(trusted.sourceMessageDateIso).getTime() + 24 * 3600000).toISOString();
  setNextAction(draft, 'expire_draft', draft.answerExpiresAt, 1, draft.rowVersion);
  draft.historyJson = appendHistory(draft.historyJson, {
    eventId: deterministicId('evt', [draft.recordId, 'mutation_draft_created', trusted.messageId]), eventType: 'mutation_draft_created',
    at: trusted.sourceMessageDateIso, actor: 'system', sourceMessageId: trusted.messageId, mutationToken: '', diff: { candidateCount: candidateIds.length },
  });
  validatePlannedRow(draft, { trusted });
  return { row: draft, mutationRequired: true, createReadBackKey: { recordId, idempotencyKey }, taskHandled: true, memoryWriteAllowed: false };
}

function planDraftQuestionReceipt(draftRow, receipt, trusted, nowIso) {
  draftRow = validatePersistedRow(draftRow, { trusted });
  assert(draftRow.rowRole === 'command_draft' && draftRow.status === 'draft' && draftRow.correlationToken, 'invalid_draft', 'Draft question receipt requires an active correlated draft');
  assert(receipt && String(receipt.chatId || '') === draftRow.chatId && /^\d+$/.test(String(receipt.messageId || '')), 'receipt_mismatch', 'Draft question receipt must match exact chat/message');
  if (draftRow.askedMessageId) {
    assert(draftRow.askedMessageId === String(receipt.messageId), 'receipt_mismatch', 'Draft was already correlated to another Telegram message');
    return { idempotent: true, mutationRequired: false, row: deepClone(draftRow) };
  }
  const at = new Date(nowIso).toISOString();
  const planned = deepClone(draftRow);
  planned.rowVersion += 1; planned.lastMutationToken = mutationToken(draftRow.recordId, draftRow.rowVersion, 'draft_question_receipt', String(receipt.messageId));
  planned.askedMessageId = String(receipt.messageId); planned.telegramActionMessageId = String(receipt.messageId); planned.telegramActionChatId = String(receipt.chatId);
  planned.lastDeliveryOutcome = 'delivered';
  planned.historyJson = appendHistory(planned.historyJson, {
    eventId: deterministicId('evt', [draftRow.recordId, 'draft_question_receipt', receipt.messageId]), eventType: 'draft_question_delivered', at,
    actor: 'system', sourceMessageId: draftRow.sourceMessageId, mutationToken: planned.lastMutationToken, diff: { askedMessageId: planned.askedMessageId },
  });
  // The expire_draft action remains semantically unchanged but its snapshot
  // token must track the persisted rowVersion.
  planned.actionToken = __require('./utils').actionToken(planned.recordId, planned.nextActionType, planned.nextActionAt, planned.actionSequence, planned.rowVersion);
  validatePlannedRow(planned, { trusted });
  return { idempotent: false, mutationRequired: true, row: planned, readBackExpectation: mutationReadBackExpectation(draftRow, planned) };
}

function planResolveMutationDraft(draftRow, targetRow, answer, trusted, nowIso) {
  draftRow = validatePersistedRow(draftRow, { trusted }); targetRow = validatePersistedRow(targetRow, { trusted });
  assert(draftRow.rowRole === 'command_draft' && draftRow.draftKind === 'mutation', 'invalid_draft', 'Expected a mutation command draft');
  assert(answer && String(answer.correlationToken || '') === draftRow.correlationToken, 'correlation_mismatch', 'Mutation draft token mismatch');
  assert(String(answer.selectedRecordId || '') === targetRow.recordId, 'correlation_mismatch', 'Selected target does not match exact target row');
  const answerMessageId = String(answer.answerMessageId || '');
  assert(/^\d+$/.test(answerMessageId), 'correlation_mismatch', 'Mutation draft answerMessageId must be numeric');
  const answerIdempotencyKey = deterministicId('idem', ['task_answer', trusted.tenantId, trusted.chatId, answerMessageId, draftRow.recordId, targetRow.recordId]);
  if (draftRow.status === 'completed' && draftRow.answerIdempotencyKey === answerIdempotencyKey) {
    return { idempotent: true, mutationRequired: false, rows: [deepClone(targetRow), deepClone(draftRow)], taskHandled: true, memoryWriteAllowed: false };
  }
  assert(draftRow.status === 'draft' && draftRow.expectedAnswerType === 'target', 'invalid_draft', 'Mutation draft is not awaiting target selection');
  assert(/^\d+$/.test(draftRow.askedMessageId || ''), 'correlation_mismatch', 'Mutation draft has no confirmed askedMessageId receipt');
  assert(['reply', 'callback'].includes(answer.mode), 'correlation_mismatch', 'Mutation draft answer mode is invalid');
  if (answer.mode === 'reply') assert(String(answer.replyToMessageId || '') === draftRow.askedMessageId, 'correlation_mismatch', 'Mutation draft reply does not target askedMessageId');
  else assert(String(answer.callbackMessageId || '') === draftRow.askedMessageId && answer.callbackScope === draftRow.callbackScope, 'correlation_mismatch', 'Mutation draft callback does not target exact question');
  if (draftRow.answerExpiresAt && new Date(nowIso) > new Date(draftRow.answerExpiresAt)) {
    assert(answer.allowLateExact === true, 'stale_answer', 'Mutation draft answer expired');
  }
  assert(answer.expectedDraftRowVersion === draftRow.rowVersion && answer.expectedTargetRowVersion === targetRow.rowVersion, 'concurrency_conflict', 'Mutation draft resolution uses stale rowVersion');
  const candidateIds = JSON.parse(draftRow.candidateTaskIdsJson || '[]');
  assert(Array.isArray(candidateIds) && candidateIds.includes(targetRow.recordId), 'correlation_mismatch', 'Selected target is outside persisted candidate set');
  assert(targetRow.tenantId === draftRow.tenantId && targetRow.ownerUserId === draftRow.ownerUserId && targetRow.chatId === draftRow.chatId, 'identity_permanent', 'Mutation draft target identity mismatch');
  const command = parseSemanticJson(draftRow.pendingCommandJson);
  const at = new Date(nowIso).toISOString();
  const history = JSON.parse(targetRow.historyJson || '[]');
  const alreadyApplied = history.some((event) => event && event.diff && event.diff.mutationDraftAnswerKey === answerIdempotencyKey);
  let targetPlan = null;
  let plannedTarget = deepClone(targetRow);
  if (!alreadyApplied) {
    targetPlan = planDirectTaskMutation(targetRow, command, trusted, at, { sourceMessageId: answerMessageId, originalText: draftRow.originalText });
    plannedTarget = targetPlan.row;
    plannedTarget.historyJson = appendHistory(plannedTarget.historyJson, {
      eventId: deterministicId('evt', [targetRow.recordId, 'mutation_draft_applied', answerIdempotencyKey]), eventType: 'mutation_draft_applied', at,
      actor: 'user', sourceMessageId: answerMessageId, mutationToken: plannedTarget.lastMutationToken,
      diff: { mutationDraftId: draftRow.recordId, mutationDraftAnswerKey: answerIdempotencyKey },
    });
    validatePlannedRow(plannedTarget, { trusted });
    targetPlan.readBackExpectation.expectedRow = deepClone(plannedTarget);
  }
  const plannedDraft = deepClone(draftRow);
  plannedDraft.rowVersion += 1; plannedDraft.lastMutationToken = mutationToken(draftRow.recordId, draftRow.rowVersion, 'resolve_mutation_draft', answerMessageId);
  terminalize(plannedDraft, 'completed', 'clarification_applied', at, false);
  plannedDraft.pendingCommandJson = ''; plannedDraft.candidateTaskIdsJson = '[]'; plannedDraft.expectedAnswerType = '';
  plannedDraft.answerMessageId = answerMessageId; plannedDraft.answerIdempotencyKey = answerIdempotencyKey; plannedDraft.answerExpiresAt = '';
  plannedDraft.leaseOwner = ''; plannedDraft.leaseUntil = ''; plannedDraft.dispatchToken = '';
  plannedDraft.historyJson = appendHistory(plannedDraft.historyJson, {
    eventId: deterministicId('evt', [draftRow.recordId, 'mutation_draft_resolved', answerIdempotencyKey]), eventType: 'mutation_draft_resolved', at,
    actor: 'user', sourceMessageId: answerMessageId, mutationToken: plannedDraft.lastMutationToken, diff: { selectedRecordId: targetRow.recordId },
  });
  validatePlannedRow(plannedDraft, { trusted });
  return {
    idempotent: false, mutationRequired: true, rows: [plannedTarget, plannedDraft], targetRow: plannedTarget, draftRow: plannedDraft,
    targetReadBackExpectation: targetPlan ? targetPlan.readBackExpectation : null,
    draftReadBackExpectation: mutationReadBackExpectation(draftRow, plannedDraft),
    writeOrder: alreadyApplied ? ['close_mutation_draft'] : ['apply_exact_target', 'close_mutation_draft'],
    recovery: alreadyApplied ? 'target_already_applied_close_draft' : 'apply_target_then_close_draft',
    taskHandled: true, memoryWriteAllowed: false,
  };
}

function planResolveCreateDraft(draftRow, answer, trusted, nowIso) {
  draftRow = validatePersistedRow(draftRow, { trusted });
  assert(answer && answer.resolvedCommand, 'invalid_draft_answer', 'Create draft answer requires a resolved semantic command');
  const resolvedCommand = parseSemanticJson(answer.resolvedCommand);
  assert(['create_task', 'create_reminder'].includes(resolvedCommand.operation) && !resolvedCommand.clarificationNeeded,
    'invalid_draft_answer', 'Create draft must resolve to a bounded non-clarifying creation command');
  assert(!resolvedCommand.recurrence, 'create_draft_series_requires_replan', 'Recurring create draft requires an explicit bounded series re-plan');
  const answerMessageId = String(answer.answerMessageId || '');
  assert(/^\d+$/.test(answerMessageId), 'correlation_mismatch', 'Create draft answerMessageId must be numeric');
  const answerIdempotencyKey = deterministicId('idem', [
    'create_draft_answer', trusted.tenantId, trusted.chatId, answerMessageId,
    draftRow.recordId, resolvedCommand.canonicalJson,
  ]);
  if (draftRow.answerMessageId === answerMessageId) {
    assert(draftRow.answerIdempotencyKey === answerIdempotencyKey, 'answer_replay_mismatch', 'Create draft answerMessageId was reused with another payload');
    return {
      idempotent: true, mutationRequired: false, row: deepClone(draftRow),
      answerIdempotencyKey, readBackExpectation: exactCurrentRowExpectation(draftRow),
      taskHandled: true, memoryWriteAllowed: false,
    };
  }
  assert(draftRow.recordType === 'task' && draftRow.rowRole === 'command_draft' && draftRow.draftKind === 'create' && draftRow.status === 'draft',
    'invalid_draft', 'Expected an active create command draft');
  assert(String(answer.correlationToken || '') === draftRow.correlationToken, 'correlation_mismatch', 'Create draft token mismatch');
  assert(/^\d+$/.test(draftRow.askedMessageId || ''), 'correlation_mismatch', 'Create draft has no confirmed askedMessageId receipt');
  assert(['reply', 'callback'].includes(answer.mode), 'correlation_mismatch', 'Create draft answer mode is invalid');
  if (answer.mode === 'reply') {
    assert(String(answer.replyToMessageId || '') === draftRow.askedMessageId, 'correlation_mismatch', 'Create draft reply does not target askedMessageId');
  } else {
    assert(String(answer.callbackMessageId || '') === draftRow.askedMessageId && answer.callbackScope === draftRow.callbackScope,
      'correlation_mismatch', 'Create draft callback does not target exact question');
