  // token must track the persisted rowVersion.
  planned.actionToken = __require('./utils').actionToken(planned.recordId, planned.nextActionType, planned.nextActionAt, planned.actionSequence, planned.rowVersion);
  validatePlannedRow(planned, { trusted });
  return { idempotent: false, mutationRequired: true, row: planned, readBackExpectation: mutationReadBackExpectation(draftRow, planned) };
