function fieldProvided(command, field) {
  return Array.isArray(command.fieldPresence) ? command.fieldPresence.includes(field) : command[field] !== undefined;
}

function mutationReadBackExpectation(previous, planned) {
  return {
    exactKey: { recordId: previous.recordId, tenantId: previous.tenantId, ownerUserId: previous.ownerUserId },
    previousRowVersion: previous.rowVersion,
    expectedRowVersion: planned.rowVersion,
    expectedMutationToken: planned.lastMutationToken,
    immutable: {
      recordId: previous.recordId, tenantId: previous.tenantId, ownerUserId: previous.ownerUserId,
      telegramUserId: previous.telegramUserId, chatId: previous.chatId,
      sourceMessageId: previous.sourceMessageId, sourceMessageDateIso: previous.sourceMessageDateIso,
    },
    expectedRow: deepClone(planned),
    requireExactlyOne: true,
