  assert(occurrenceRow.seriesId === seriesRow.recordId, 'invalid_series_link', 'Occurrence does not belong to exact series');
  assert(CLOSED_OCCURRENCE_STATUSES.includes(occurrenceRow.status), 'invalid_series_transition', 'Only a terminal occurrence can advance a series');
  assert(seriesRow.tenantId === occurrenceRow.tenantId && seriesRow.ownerUserId === occurrenceRow.ownerUserId && seriesRow.chatId === occurrenceRow.chatId, 'identity_permanent', 'Series/occurrence identity mismatch');
  assert(Array.isArray(tableRows), 'invalid_series_input', 'tableRows must be the exact same-tenant table snapshot');
  tableRows = tableRows.map((row) => validatePersistedRow(row));
  assertNoLogicalDuplicates(tableRows);
  for (const row of tableRows) {
    assert(row.tenantId === seriesRow.tenantId && row.ownerUserId === seriesRow.ownerUserId, 'identity_permanent', 'Foreign row in series snapshot');
  }
  const now = new Date(nowIso);
  assert(Number.isFinite(now.getTime()), 'invalid_datetime', 'nowIso is invalid');
  const rule = parseJson(seriesRow.recurrenceRuleJson, 'recurrenceRuleJson');
  assert(['daily', 'weekly'].includes(rule.frequency), 'unsupported_recurrence', 'Bounded lifecycle supports daily/weekly only');
  const history = parseJson(seriesRow.historyJson || '[]', 'historyJson');
  const processedByHistory = history.some((event) => event && event.diff && event.diff.processedOccurrenceId === occurrenceRow.recordId);
  const processedByMonotonicSlot = !!seriesRow.lastOccurrenceAt && new Date(seriesRow.lastOccurrenceAt) >= new Date(occurrenceRow.occurrenceScheduledFor);
  const alreadyProcessed = processedByHistory || processedByMonotonicSlot;
  const slot = nextRecurrenceSlot(
    rule,
    occurrenceRow.occurrenceScheduledFor,
    seriesRow.recurrenceStartLocalDate,
    seriesRow.recurrenceEndLocalDate || null,
    occurrenceRow.occurrenceOrdinal,
  );
  const completedReplayAllowed = seriesRow.status === 'completed' && processedByHistory &&
    seriesRow.lastOccurrenceAt === occurrenceRow.occurrenceScheduledFor &&
    !seriesRow.currentOccurrenceId && seriesRow.nextActionType === 'none' && !slot;
  assert(seriesRow.status === 'active' || completedReplayAllowed, 'series_not_active', 'Paused/cancelled/completed/failed_review series cannot advance or create occurrences');
  const expectedNextIdentity = slot ? occurrenceIdentity(seriesRow, slot) : null;
  const occurrences = tableRows.filter((row) => row && row.recordType === 'task' && row.rowRole === 'occurrence' && row.seriesId === seriesRow.recordId);
  const activeOccurrences = occurrences.filter((row) => !CLOSED_OCCURRENCE_STATUSES.includes(row.status) && row.status !== 'failed_review');
  assert(activeOccurrences.length <= 1, 'duplicate_nonterminal_occurrence', 'Series has more than one nonterminal occurrence');
  if (activeOccurrences.length === 1) {
    assert(expectedNextIdentity && activeOccurrences[0].recordId === expectedNextIdentity.recordId, 'duplicate_nonterminal_occurrence', 'Unexpected nonterminal occurrence blocks series advance');
  }
  const existingNextMatches = expectedNextIdentity
    ? occurrences.filter((row) => row.recordId === expectedNextIdentity.recordId || row.idempotencyKey === expectedNextIdentity.idempotencyKey)
    : [];
  assert(existingNextMatches.length <= 1, 'duplicate_logical_row', 'Duplicate deterministic next occurrence');
  const existingNext = existingNextMatches[0] || null;
  if (existingNext) verifyExistingOccurrence(existingNext, expectedNextIdentity, seriesRow, trusted);

  if (seriesRow.currentOccurrenceId && seriesRow.currentOccurrenceId !== occurrenceRow.recordId) {
    assert(expectedNextIdentity && seriesRow.currentOccurrenceId === expectedNextIdentity.recordId, 'concurrency_conflict', 'Series pointer changed to an unexpected occurrence');
  }

  let nextOccurrence = existingNext;
  let occurrenceUpsert = null;
  if (slot && !existingNext) {
    nextOccurrence = buildNextOccurrence(seriesRow, occurrenceRow, slot, now.toISOString());
    validatePlannedRow(nextOccurrence, { trusted });
    occurrenceUpsert = {
      mode: 'deterministic_upsert',
      exactKey: { recordId: nextOccurrence.recordId, idempotencyKey: nextOccurrence.idempotencyKey, tenantId: nextOccurrence.tenantId, ownerUserId: nextOccurrence.ownerUserId },
      row: nextOccurrence,
      readBackExpectation: createReadBackExpectation(nextOccurrence),
    };
  }

  const plannedSeries = deepClone(seriesRow);
  const desiredPointer = nextOccurrence ? nextOccurrence.recordId : '';
  const pointerNeedsRepair = plannedSeries.currentOccurrenceId !== desiredPointer;
  const endNeedsFinalize = !slot && (plannedSeries.status !== 'completed' || plannedSeries.nextActionType !== 'none');
  const counterNeedsApply = !alreadyProcessed;
  const seriesMutationRequired = pointerNeedsRepair || endNeedsFinalize || counterNeedsApply;
  let seriesReadBackExpectation = null;
  if (seriesMutationRequired) {
    plannedSeries.rowVersion += 1;
    plannedSeries.lastMutationToken = mutationToken(seriesRow.recordId, seriesRow.rowVersion, 'advance_series', occurrenceRow.recordId);
    if (counterNeedsApply) incrementCounter(plannedSeries, occurrenceRow.status);
    plannedSeries.currentOccurrenceId = desiredPointer;
    plannedSeries.lastOccurrenceAt = maxIso(plannedSeries.lastOccurrenceAt, occurrenceRow.occurrenceScheduledFor);
    plannedSeries.nextOccurrenceAt = slot ? slot.utc : '';
    plannedSeries.stateChangedAt = now.toISOString();
    if (!slot) {
      plannedSeries.status = 'completed'; plannedSeries.statusReason = 'recurrence_finished'; plannedSeries.terminalAt = now.toISOString();
    }
    setNextAction(plannedSeries, 'none', '', plannedSeries.actionSequence + 1, plannedSeries.rowVersion);
    if (counterNeedsApply) {
      plannedSeries.historyJson = appendHistory(plannedSeries.historyJson, {
        eventId: deterministicId('evt', [seriesRow.recordId, 'advance_series', occurrenceRow.recordId]),
        eventType: 'occurrence_processed', at: now.toISOString(), actor: 'scheduler', sourceMessageId: occurrenceRow.sourceMessageId,
        mutationToken: plannedSeries.lastMutationToken,
        diff: { processedOccurrenceId: occurrenceRow.recordId, terminalStatus: occurrenceRow.status, nextOccurrenceId: desiredPointer },
      });
    }
    validatePlannedRow(plannedSeries, { trusted });
    seriesReadBackExpectation = mutationReadBackExpectation(seriesRow, plannedSeries);
  }

  let plannedTerminalOccurrence = occurrenceRow;
  let terminalReadBackExpectation = null;
  if (occurrenceRow.nextActionType === 'advance_series') {
    plannedTerminalOccurrence = deepClone(occurrenceRow);
    plannedTerminalOccurrence.rowVersion += 1;
    plannedTerminalOccurrence.lastMutationToken = mutationToken(occurrenceRow.recordId, occurrenceRow.rowVersion, 'advance_series_done', seriesRow.recordId);
    plannedTerminalOccurrence.lastActionType = 'advance_series'; plannedTerminalOccurrence.lastActionAt = now.toISOString();
    setNextAction(plannedTerminalOccurrence, 'none', '', plannedTerminalOccurrence.actionSequence + 1, plannedTerminalOccurrence.rowVersion);
    validatePlannedRow(plannedTerminalOccurrence, { trusted });
    terminalReadBackExpectation = mutationReadBackExpectation(occurrenceRow, plannedTerminalOccurrence);
  } else {
    assert(alreadyProcessed, 'invalid_series_transition', 'Unprocessed terminal occurrence must carry advance_series action');
  }

  const noMutation = !seriesMutationRequired && !occurrenceUpsert && !terminalReadBackExpectation;
  return {
    idempotent: noMutation,
    processedOccurrenceId: occurrenceRow.recordId,
    seriesRow: seriesMutationRequired ? plannedSeries : deepClone(seriesRow),
    terminalOccurrenceRow: deepClone(plannedTerminalOccurrence),
    nextOccurrenceRow: nextOccurrence ? deepClone(nextOccurrence) : null,
    occurrenceUpsert,
    seriesReadBackExpectation,
    terminalReadBackExpectation,
    writeOrder: ['upsert_next_occurrence', 'update_series_pointer_and_counter', 'clear_terminal_occurrence_action'],
    recovery: existingNext ? 'reuse_existing_deterministic_occurrence' : occurrenceUpsert ? 'create_deterministic_occurrence' : slot ? 'pointer_already_resolved' : 'series_ended',
    uniquenessExpectation: { seriesId: seriesRow.recordId, maxNonterminalOccurrences: slot ? 1 : 0 },
  };
}

function occurrenceIdentity(series, slot) {
  return {
    recordId: deterministicId('occ', [series.tenantId, series.recordId, slot.utc]),
    occurrenceKey: deterministicId('occ_key', [series.recordId, slot.utc]),
    idempotencyKey: deterministicId('idem', ['task_occurrence', series.tenantId, series.recordId, slot.utc]),
  };
}

function buildNextOccurrence(series, previous, slot, nowIso) {
  const identity = occurrenceIdentity(series, slot);
  const row = deepClone(previous);
  row.recordId = identity.recordId; row.taskId = identity.recordId; row.occurrenceKey = identity.occurrenceKey; row.idempotencyKey = identity.idempotencyKey;
  row.occurrenceScheduledFor = slot.utc; row.occurrenceOrdinal = slot.ordinal;
  row.status = 'pending'; row.statusReason = 'occurrence_created'; row.stateChangedAt = nowIso; row.completedAt = ''; row.terminalAt = ''; row.completionNote = ''; row.lastAnswerText = '';
  row.dueDate = slot.localDate; row.dueAt = slot.allDay ? '' : slot.utc; row.scheduleKind = slot.allDay ? 'date' : 'exact';
  row.snoozedUntil = ''; row.reminderCursor = 0; row.lastReminderAt = ''; row.reminderCount = 0; row.completionCheckAt = '';
  row.nextActionType = 'none'; row.nextActionAt = ''; row.actionSequence = 0; row.actionToken = ''; row.lastActionType = ''; row.lastActionAt = '';
  row.correlationToken = ''; row.askedMessageId = ''; row.answerMessageId = ''; row.answerExpiresAt = ''; row.answerIdempotencyKey = '';
  row.telegramActionMessageId = ''; row.telegramActionChatId = ''; row.rowVersion = 1; row.lastMutationToken = '';
  row.leaseOwner = ''; row.leaseUntil = ''; row.dispatchToken = ''; row.lastDeliveredActionToken = ''; row.lastDeliveryOutcome = 'none'; row.attemptCount = 0; row.nextRetryAt = ''; row.lastError = ''; row.lastErrorAt = '';
  row.historyJson = canonicalJson([{ eventId: deterministicId('evt', [row.recordId, 'occurrence_created', slot.utc]), eventType: 'occurrence_created', at: nowIso, actor: 'scheduler', sourceMessageId: row.sourceMessageId, mutationToken: '', diff: {} }]);
  planInitialTaskAction(row, nowIso);
  return row;
}

function verifyExistingOccurrence(row, identity, series, trusted) {
  row = validatePersistedRow(row, { trusted });
  assert(row.recordType === 'task' && row.rowRole === 'occurrence' && row.seriesId === series.recordId, 'invalid_series_link', 'Existing deterministic row is not this series occurrence');
  assert(row.recordId === identity.recordId && row.occurrenceKey === identity.occurrenceKey && row.idempotencyKey === identity.idempotencyKey, 'duplicate_logical_row', 'Existing occurrence identity mismatch');
}

function planCancelSeries(seriesRow, occurrenceRow, trusted, nowIso, options) {
  seriesRow = validatePersistedRow(seriesRow, { trusted });
  assert(seriesRow.recordType === 'series', 'invalid_series_link', 'Series cancellation requires a series row');
  const now = new Date(nowIso);
  assert(Number.isFinite(now.getTime()), 'invalid_datetime', 'Series cancellation time is invalid');
  let occurrence = occurrenceRow ? validatePersistedRow(occurrenceRow, { trusted }) : null;
  if (seriesRow.currentOccurrenceId) {
    assert(occurrence && occurrence.recordId === seriesRow.currentOccurrenceId && occurrence.seriesId === seriesRow.recordId, 'invalid_series_link', 'Current series occurrence must be supplied exactly');
  } else assert(!occurrence || occurrence.seriesId === seriesRow.recordId, 'invalid_series_link', 'Supplied occurrence does not belong to series');
  const policy = (options && options.currentOccurrencePolicy) || '';
  const occurrenceNonterminal = occurrence && !CLOSED_OCCURRENCE_STATUSES.includes(occurrence.status) && occurrence.status !== 'failed_review';
  if (occurrenceNonterminal) assert(policy === 'cancel_current', 'series_cancel_policy_required', 'Active occurrence requires explicit cancel_current policy');
  const sourceId = String((options && options.sourceMessageId) || 'series_cancel');
  const seriesAlreadyCancelled = seriesRow.status === 'cancelled' && !seriesRow.currentOccurrenceId && seriesRow.nextActionType === 'none';
  assert(['active', 'paused', 'cancelled'].includes(seriesRow.status), 'invalid_series_transition', 'Completed/failed_review series cannot be cancelled automatically');
  if (!seriesAlreadyCancelled) {
    assertUserMutationLeaseFree(seriesRow, now.toISOString());
    if (occurrence) assertUserMutationLeaseFree(occurrence, now.toISOString());
  }

  let plannedSeries = deepClone(seriesRow);
  let seriesReadBackExpectation = null;
  if (!seriesAlreadyCancelled) {
    plannedSeries.rowVersion += 1;
    plannedSeries.lastMutationToken = mutationToken(seriesRow.recordId, seriesRow.rowVersion, 'cancel_series', sourceId);
    plannedSeries.status = 'cancelled'; plannedSeries.statusReason = 'user_cancelled_series'; plannedSeries.stateChangedAt = now.toISOString(); plannedSeries.terminalAt = now.toISOString();
    plannedSeries.currentOccurrenceId = ''; plannedSeries.nextOccurrenceAt = ''; plannedSeries.pendingCommandJson = '';
    plannedSeries.leaseOwner = ''; plannedSeries.leaseUntil = ''; plannedSeries.dispatchToken = '';
    setNextAction(plannedSeries, 'none', '', seriesRow.actionSequence + 1, plannedSeries.rowVersion);
    plannedSeries.historyJson = appendHistory(plannedSeries.historyJson, {
      eventId: deterministicId('evt', [seriesRow.recordId, 'cancel_series', sourceId]), eventType: 'cancel_series', at: now.toISOString(), actor: 'user',
      sourceMessageId: sourceId, mutationToken: plannedSeries.lastMutationToken, diff: { currentOccurrencePolicy: occurrenceNonterminal ? policy : 'already_terminal' },
    });
    validatePlannedRow(plannedSeries, { trusted });
    seriesReadBackExpectation = mutationReadBackExpectation(seriesRow, plannedSeries);
  }

  let plannedOccurrence = occurrence ? deepClone(occurrence) : null;
  let occurrenceReadBackExpectation = null;
  const occurrenceNeedsCancel = occurrenceNonterminal;
  const terminalAdvanceNeedsClear = occurrence && CLOSED_OCCURRENCE_STATUSES.includes(occurrence.status) && occurrence.nextActionType === 'advance_series';
  if (occurrenceNeedsCancel || terminalAdvanceNeedsClear) assertUserMutationLeaseFree(occurrence, now.toISOString());
  if (occurrenceNeedsCancel || terminalAdvanceNeedsClear) {
    plannedOccurrence.rowVersion += 1;
    plannedOccurrence.lastMutationToken = mutationToken(occurrence.recordId, occurrence.rowVersion, occurrenceNeedsCancel ? 'cancel_series_occurrence' : 'clear_cancelled_series_advance', sourceId);
    if (occurrenceNeedsCancel) {
      plannedOccurrence.status = 'cancelled'; plannedOccurrence.statusReason = 'series_cancelled_current_occurrence'; plannedOccurrence.stateChangedAt = now.toISOString(); plannedOccurrence.terminalAt = now.toISOString();
    }
    plannedOccurrence.leaseOwner = ''; plannedOccurrence.leaseUntil = ''; plannedOccurrence.dispatchToken = '';
    setNextAction(plannedOccurrence, 'none', '', occurrence.actionSequence + 1, plannedOccurrence.rowVersion);
    plannedOccurrence.historyJson = appendHistory(plannedOccurrence.historyJson, {
      eventId: deterministicId('evt', [occurrence.recordId, 'series_cancel_occurrence', sourceId]), eventType: occurrenceNeedsCancel ? 'series_cancelled_occurrence' : 'series_cancelled_advance_cleared',
      at: now.toISOString(), actor: 'user', sourceMessageId: sourceId, mutationToken: plannedOccurrence.lastMutationToken, diff: { seriesId: seriesRow.recordId },
    });
    validatePlannedRow(plannedOccurrence, { trusted });
    occurrenceReadBackExpectation = mutationReadBackExpectation(occurrence, plannedOccurrence);
  }
  const idempotent = !seriesReadBackExpectation && !occurrenceReadBackExpectation;
  return {
    idempotent, mutationRequired: !idempotent, seriesRow: plannedSeries, occurrenceRow: plannedOccurrence,
    seriesReadBackExpectation, occurrenceReadBackExpectation,
    writeOrder: [seriesReadBackExpectation ? 'cancel_series_gate' : null, occurrenceReadBackExpectation ? 'cancel_current_occurrence' : null].filter(Boolean),
    recovery: seriesAlreadyCancelled && occurrenceReadBackExpectation ? 'finish_current_occurrence_after_series_gate' : idempotent ? 'already_cancelled' : 'cancel_series_then_current_occurrence',
    preventsNewOccurrences: true,
  };
}

function planResumeSeries(seriesRow, occurrenceRow, tableRows, trusted, nowIso, options) {
  seriesRow = validatePersistedRow(seriesRow, { trusted });
  assert(seriesRow.recordType === 'series', 'invalid_series_link', 'Series resume requires an exact series row');
  const now = new Date(nowIso);
  assert(Number.isFinite(now.getTime()), 'invalid_datetime', 'Series resume time is invalid');
  const sourceId = String((options && options.sourceMessageId) || trusted.messageId || 'series_resume');
  const sourceKey = deterministicId('series_resume_src', [seriesRow.recordId, trusted.sourceUpdateId, sourceId]);
  const history = parseJson(seriesRow.historyJson || '[]', 'historyJson');
  if (seriesRow.status === 'active' && history.some((event) => event && event.diff && event.diff.seriesResumeSourceKey === sourceKey)) {
    return { idempotent: true, mutationRequired: false, seriesRow: deepClone(seriesRow), recovery: 'same_source_replay' };
  }
  assert(seriesRow.status === 'paused' && seriesRow.statusReason !== 'mutation_in_progress',
    'invalid_series_transition', 'Only a stable paused series can enter the resume saga');
  let occurrence = occurrenceRow ? validatePersistedRow(occurrenceRow, { trusted }) : null;
  if (seriesRow.currentOccurrenceId) {
    assert(occurrence && occurrence.recordId === seriesRow.currentOccurrenceId && occurrence.seriesId === seriesRow.recordId,
      'invalid_series_link', 'Resume requires the exact current occurrence');
  }
  assert(occurrence, 'series_resume_template_required', 'Resume requires an exact occurrence template to preserve task policy');
  assertUserMutationLeaseFree(seriesRow, now.toISOString());
  assertUserMutationLeaseFree(occurrence, now.toISOString());
  const snapshot = (tableRows || [seriesRow, occurrence]).map((row) => validatePersistedRow(row, { trusted }));
  assertNoLogicalDuplicates(snapshot);
  const rule = parseJson(seriesRow.recurrenceRuleJson, 'recurrenceRuleJson');
  assert(occurrence.status !== 'failed_review', 'invalid_series_transition', 'failed_review occurrence cannot be folded by resume automatically');
  const nonterminal = !CLOSED_OCCURRENCE_STATUSES.includes(occurrence.status) && occurrence.status !== 'failed_review';
  const processedByHistory = history.some((event) => event && event.diff && event.diff.processedOccurrenceId === occurrence.recordId);
  const processedByMonotonicSlot = !!seriesRow.lastOccurrenceAt && new Date(seriesRow.lastOccurrenceAt) >= new Date(occurrence.occurrenceScheduledFor);
  const alreadyProcessed = processedByHistory || processedByMonotonicSlot;
  let anchor = '';
  if (nonterminal) {
    if (occurrence.nextActionAt) anchor = occurrence.nextActionAt;
    else if (['exact', 'date'].includes(occurrence.scheduleKind)) anchor = taskActionAnchorAt(occurrence);
    else if (occurrence.scheduleKind === 'window') anchor = occurrence.windowEndAt;
  }
  const keepCurrent = nonterminal && anchor && new Date(anchor) > now;
  const nextAfter = new Date(Math.max(now.getTime(), new Date(occurrence.occurrenceScheduledFor).getTime())).toISOString();
  const slot = keepCurrent ? null : nextRecurrenceSlot(
    rule, nextAfter, seriesRow.recurrenceStartLocalDate,
    seriesRow.recurrenceEndLocalDate || null, occurrence.occurrenceOrdinal,
  );
  const identity = slot ? occurrenceIdentity(seriesRow, slot) : null;
  const existingMatches = identity ? snapshot.filter((row) => row.recordId === identity.recordId || row.idempotencyKey === identity.idempotencyKey) : [];
  assert(existingMatches.length <= 1, 'duplicate_logical_row', 'Resume found duplicate deterministic occurrence');
  let nextOccurrence = existingMatches[0] || null;
  if (nextOccurrence) verifyExistingOccurrence(nextOccurrence, identity, seriesRow, trusted);
  assert(keepCurrent || !nextOccurrence || nextOccurrence.recordId !== occurrence.recordId,
    'recurrence_slot_reuse', 'Resume cannot point a series back to the occurrence being closed');
  let occurrenceUpsert = null;
  if (slot && !nextOccurrence) {
    nextOccurrence = buildNextOccurrence(seriesRow, occurrence, slot, now.toISOString());
    validatePlannedRow(nextOccurrence, { trusted });
    occurrenceUpsert = {
      mode: 'deterministic_upsert',
      exactKey: { recordId: nextOccurrence.recordId, idempotencyKey: nextOccurrence.idempotencyKey, tenantId: nextOccurrence.tenantId, ownerUserId: nextOccurrence.ownerUserId },
      row: nextOccurrence, readBackExpectation: createReadBackExpectation(nextOccurrence),
    };
  }

  const claimedSeries = deepClone(seriesRow);
  claimedSeries.rowVersion += 1;
  claimedSeries.lastMutationToken = mutationToken(seriesRow.recordId, seriesRow.rowVersion, 'claim_resume_series', sourceId);
  claimedSeries.status = 'paused'; claimedSeries.statusReason = 'mutation_in_progress'; claimedSeries.stateChangedAt = now.toISOString();
  claimedSeries.pendingCommandJson = canonicalJson({ kind: 'resume_series_v1', sourceKey, targetOccurrenceId: keepCurrent ? occurrence.recordId : (nextOccurrence && nextOccurrence.recordId) || '' });
  claimedSeries.leaseOwner = ''; claimedSeries.leaseUntil = ''; claimedSeries.dispatchToken = '';
  setNextAction(claimedSeries, 'none', '', seriesRow.actionSequence + 1, claimedSeries.rowVersion);
  validatePlannedRow(claimedSeries, { trusted });

  let staleOccurrenceRow = null; let staleOccurrenceReadBackExpectation = null;
  const clearTerminalAdvance = !keepCurrent && !nonterminal && occurrence.nextActionType === 'advance_series';
  if ((!keepCurrent && nonterminal) || clearTerminalAdvance) {
    staleOccurrenceRow = deepClone(occurrence);
    staleOccurrenceRow.rowVersion += 1;
    staleOccurrenceRow.lastMutationToken = mutationToken(occurrence.recordId, occurrence.rowVersion,
      nonterminal ? 'resume_skip_stale_occurrence' : 'resume_fold_terminal_occurrence', sourceId);
    if (nonterminal) {
      staleOccurrenceRow.status = 'skipped'; staleOccurrenceRow.statusReason = 'series_resume_skipped_stale_occurrence';
      staleOccurrenceRow.stateChangedAt = now.toISOString(); staleOccurrenceRow.terminalAt = now.toISOString();
    } else {
      staleOccurrenceRow.lastActionType = 'advance_series'; staleOccurrenceRow.lastActionAt = now.toISOString();
    }
    staleOccurrenceRow.leaseOwner = ''; staleOccurrenceRow.leaseUntil = ''; staleOccurrenceRow.dispatchToken = '';
    setNextAction(staleOccurrenceRow, 'none', '', occurrence.actionSequence + 1, staleOccurrenceRow.rowVersion);
    staleOccurrenceRow.historyJson = appendHistory(staleOccurrenceRow.historyJson, {
      eventId: deterministicId('evt', [occurrence.recordId, nonterminal ? 'resume_skip_stale' : 'resume_fold_terminal', sourceKey]),
      eventType: nonterminal ? 'series_resume_skipped_stale_occurrence' : 'series_resume_folded_terminal_occurrence',
      at: now.toISOString(), actor: 'user', sourceMessageId: sourceId, mutationToken: staleOccurrenceRow.lastMutationToken,
      diff: { seriesId: seriesRow.recordId, terminalStatus: nonterminal ? 'skipped' : occurrence.status },
    });
    validatePlannedRow(staleOccurrenceRow, { trusted });
    staleOccurrenceReadBackExpectation = mutationReadBackExpectation(occurrence, staleOccurrenceRow);
  }

  const finalSeries = deepClone(claimedSeries);
  finalSeries.rowVersion += 1;
  finalSeries.lastMutationToken = mutationToken(seriesRow.recordId, claimedSeries.rowVersion, 'finalize_resume_series', sourceId);
  finalSeries.pendingCommandJson = ''; finalSeries.stateChangedAt = now.toISOString();
  const foldOccurrence = !keepCurrent && !alreadyProcessed;
  const foldedStatus = nonterminal ? 'skipped' : occurrence.status;
  if (keepCurrent) {
    finalSeries.status = 'active'; finalSeries.statusReason = 'user_resumed_series';
    finalSeries.currentOccurrenceId = occurrence.recordId; finalSeries.nextOccurrenceAt = occurrence.occurrenceScheduledFor;
  } else if (nextOccurrence) {
    finalSeries.status = 'active'; finalSeries.statusReason = 'user_resumed_series';
    finalSeries.currentOccurrenceId = nextOccurrence.recordId; finalSeries.nextOccurrenceAt = nextOccurrence.occurrenceScheduledFor;
    if (foldOccurrence) incrementCounter(finalSeries, foldedStatus);
    finalSeries.lastOccurrenceAt = maxIso(finalSeries.lastOccurrenceAt, occurrence.occurrenceScheduledFor);
  } else {
    finalSeries.status = 'completed'; finalSeries.statusReason = 'recurrence_finished'; finalSeries.terminalAt = now.toISOString();
    finalSeries.currentOccurrenceId = ''; finalSeries.nextOccurrenceAt = '';
    if (foldOccurrence) incrementCounter(finalSeries, foldedStatus);
    finalSeries.lastOccurrenceAt = maxIso(finalSeries.lastOccurrenceAt, occurrence.occurrenceScheduledFor);
  }
  setNextAction(finalSeries, 'none', '', claimedSeries.actionSequence + 1, finalSeries.rowVersion);
  finalSeries.historyJson = appendHistory(finalSeries.historyJson, {
    eventId: deterministicId('evt', [seriesRow.recordId, 'resume_series', sourceKey]), eventType: 'resume_series', at: now.toISOString(), actor: 'user',
    sourceMessageId: sourceId, mutationToken: finalSeries.lastMutationToken,
    diff: {
      seriesResumeSourceKey: sourceKey, skippedStaleOccurrence: !keepCurrent && nonterminal,
      currentOccurrenceId: finalSeries.currentOccurrenceId,
      processedOccurrenceId: foldOccurrence ? occurrence.recordId : '', terminalStatus: foldOccurrence ? foldedStatus : '',
    },
  });
  validatePlannedRow(finalSeries, { trusted });
  return {
    idempotent: false, mutationRequired: true, claimSeriesRow: claimedSeries, seriesRow: finalSeries,
    currentOccurrenceRow: staleOccurrenceRow || deepClone(occurrence), nextOccurrenceRow: nextOccurrence ? deepClone(nextOccurrence) : null,
    claimReadBackExpectation: mutationReadBackExpectation(seriesRow, claimedSeries),
    occurrenceUpsert, staleOccurrenceReadBackExpectation,
    currentOccurrenceReadBackExpectation: staleOccurrenceReadBackExpectation,
    finalReadBackExpectation: mutationReadBackExpectation(claimedSeries, finalSeries),
    writeOrder: ['claim_series_paused', occurrenceUpsert ? 'upsert_next_occurrence' : null, staleOccurrenceReadBackExpectation ? 'close_or_fold_current_occurrence' : null, 'finalize_series_active'].filter(Boolean),
    recovery: 'partial_state_stays_paused_mutation_in_progress', noBackfill: true,
  };
}

function planFailSeriesMutation(claimedSeriesRow, trusted, nowIso, sanitizedError) {
  claimedSeriesRow = validatePersistedRow(claimedSeriesRow, { trusted });
  assert(claimedSeriesRow.recordType === 'series' && claimedSeriesRow.status === 'paused' && claimedSeriesRow.statusReason === 'mutation_in_progress' && claimedSeriesRow.pendingCommandJson,
    'invalid_series_transition', 'Only a claimed partial series mutation can fail into review');
